{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://raw.githubusercontent.com/TIANLI0/FluentSetup/main/shared/schemas/fluentsetup.project.schema.json",
  "title": "FluentSetup project (fluentsetup.json)",
  "description": "Describes a Windows installer built by FluentSetup. Mirrors src/Builder.Core/Model/ProjectModel.cs and the checks in ProjectValidator.cs / ExtensionValidator.cs. Property names are camelCase (matched case-insensitively by the builder); // comments and trailing commas are accepted by the builder. Unknown properties are not rejected: at the root and in app, files, install, ui, output and signing they are kept on save, elsewhere they are ignored. Relative file paths are resolved against the folder that contains the project file.",
  "type": "object",
  "required": [
    "app",
    "files"
  ],
  "properties": {
    "$schema": {
      "type": [
        "string",
        "null"
      ],
      "description": "Optional reference to this schema for editors. Ignored by the builder. New projects get \"https://raw.githubusercontent.com/TIANLI0/FluentSetup/main/shared/schemas/fluentsetup.project.schema.json\"."
    },
    "schemaVersion": {
      "type": "integer",
      "maximum": 1,
      "default": 1,
      "description": "Project format version. Files with a value greater than 1 are rejected by this FluentSetup; the value is rewritten to 1 on load."
    },
    "variables": {
      "type": "object",
      "default": {},
      "propertyNames": {
        "pattern": "^[A-Za-z_][A-Za-z0-9_.-]{0,63}$"
      },
      "additionalProperties": {
        "type": "string"
      },
      "description": "Values for $(Name) placeholders in any string of the project, e.g. { \"Version\": \"1.2.0\" } with \"version\": \"$(Version)\". \"fluentsetup build -D Version=1.2.1\" overrides them (CI release builds). \"$$(\" writes a literal \"$(\"."
    },
    "app": {
      "$ref": "#/$defs/app"
    },
    "files": {
      "$ref": "#/$defs/files"
    },
    "
